package com.blog.service.impl; import com.blog.dto.AuthDtos.*; import com.blog.dto.ProfileDtos.*; import com.blog.entity.User; import com.blog.exception.ApiExceptions.*; import com.blog.mapper.BlogMapper; import com.blog.repository.UserRepository; import com.blog.service.BlogServices.ProfileService; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor @Transactional public class ProfileServiceImpl implements ProfileService {private final UserRepository users;private final PasswordEncoder encoder;private final BlogMapper mapper; @Transactional(readOnly=true) public UserResponse profile(String email){return mapper.user(user(email));} public UserResponse update(ProfileUpdateRequest r,String email){var u=user(email);u.setFirstName(r.firstName());u.setLastName(r.lastName());if(r.newPassword()!=null){if(r.currentPassword()==null||!encoder.matches(r.currentPassword(),u.getPassword()))throw new BadRequestException("Current password is invalid");u.setPassword(encoder.encode(r.newPassword()));}return mapper.user(u);}private User user(String e){return users.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}}
